import fs from 'node:fs';
import path from 'node:path';
import { Container } from '@/components/layout/container';
import { LargeTitle } from '@/components/ios/large-title';
import { ReviewClient, type CardItem } from './review-client';

/** public/cards.json is generated by scripts/build-cards.mjs before `next build`. */
function readCards(): CardItem[] | undefined {
  try {
    return JSON.parse(fs.readFileSync(path.join(process.cwd(), 'public', 'cards.json'), 'utf8'));
  } catch {
    return undefined;
  }
}

export default function ReviewPage() {
  return (
    <Container className="py-12 md:py-16">
      <div className="mx-auto max-w-screen-md">
        <LargeTitle subtitle="Review your flashcards using spaced repetition.">Daily Review</LargeTitle>
        <ReviewClient initialCards={readCards()} />
      </div>
    </Container>
  );
}
